const input = $input.first().json;
const body = input.body ?? input;
const headers = input.headers ?? {};
const suppliedSecret = String(headers["x-webhook-secret"] ?? headers["X-Webhook-Secret"] ?? "");
const expectedSecret = String(input.WEBHOOK_SECRET ?? "");
const recipients = Array.isArray(body.whatsapp?.recipients) ? body.whatsapp.recipients : [];
const supportedEvents = ["daily_equipment_audit", "fmc_offline"];
const validEvent = supportedEvents.includes(String(body.event ?? "")) && Number(body.version) === 1;
const configured = expectedSecret && !expectedSecret.startsWith("REPLACE_") && input.WA_PHONE_NUMBER_ID && !String(input.WA_PHONE_NUMBER_ID).startsWith("REPLACE_") && input.WA_ACCESS_TOKEN && !String(input.WA_ACCESS_TOKEN).startsWith("REPLACE_");
const authorized = configured && suppliedSecret === expectedSecret;
let error = "";
if (!configured) error = "n8n WhatsApp workflow configuration is incomplete";
else if (!authorized) error = "Invalid or missing X-Webhook-Secret";
else if (!validEvent) error = "Unsupported webhook event or version";
else if (!recipients.length) error = "No WhatsApp recipients were supplied";
return [{ json: { ...input, body, recipients, authorized, valid_event: validEvent, has_recipients: recipients.length > 0, request_valid: authorized && validEvent && recipients.length > 0, validation_error: error } }];

const input = $input.first().json;
const body = input.body;

function compact(value, fallback = "") {
  return String(value ?? fallback).replace(/[\n\r\t]+/g, " ").replace(/\s{2,}/g, " ").trim();
}

function truncate(value, maxLength) {
  const text = compact(value);
  return text.length > maxLength ? `${text.slice(0, maxLength - 3)}...` : text;
}

function auditTemplateParameters() {
  const customerName = compact(body.customer?.name, "Customer");
  const auditTime = compact(body.audit?.scheduled_for, "Unknown");
  const summary = body.summary ?? {};
  const devices = Array.isArray(body.devices) ? body.devices : [];
  const siteLines = devices.map((device) => {
    const counts = device.counts ?? {};
    const name = compact(device.device_name ?? device.device_ident, "Device");
    const missingNames = (device.assets ?? []).filter((asset) => asset.status === "missing").map((asset) => compact(asset.asset_name)).filter(Boolean);
    const movedNames = (device.assets ?? []).filter((asset) => asset.status === "equipment_moved").map((asset) => `${compact(asset.asset_name, "Asset")} to ${compact(asset.detected_device_name ?? asset.detected_device_ident, "another site")}`).filter(Boolean);
    const offlineNames = (device.assets ?? []).filter((asset) => asset.status === "device_offline").map((asset) => compact(asset.asset_name)).filter(Boolean);
    let line = `${name}: ${Number(counts.present ?? 0)} in range, ${Number(counts.missing ?? 0)} missing, ${Number(counts.equipment_moved ?? 0)} moved, ${Number(counts.device_offline ?? 0)} site offline`;
    if (missingNames.length) line += `; Missing: ${missingNames.join(", ")}`;
    if (movedNames.length) line += `; Moved: ${movedNames.join(", ")}`;
    if (offlineNames.length) line += `; Site offline: ${offlineNames.join(", ")}`;
    return line;
  });
  const siteSummary = truncate(siteLines.join(" | ") || "No device details were supplied.", 950);
  return {
    templateName: compact(input.WA_TEMPLATE_NAME ?? body.whatsapp?.template_name, "ble_notification"),
    languageCode: compact(body.whatsapp?.language ?? input.WA_LANGUAGE_CODE, "en"),
    parameters: [
      customerName,
      auditTime,
      String(Number(summary.present ?? 0)),
      String(Number(summary.missing ?? 0)),
      String(Number(summary.equipment_moved ?? 0)),
      String(Number(summary.device_offline ?? 0)),
      siteSummary,
    ],
  };
}

function fmcOfflineTemplateParameters() {
  const device = body.device ?? {};
  return {
    templateName: compact(input.FMC_OFFLINE_TEMPLATE_NAME ?? body.whatsapp?.template_name, "ble_fmc_offline"),
    languageCode: compact(body.whatsapp?.language ?? input.WA_LANGUAGE_CODE, "en"),
    parameters: [
      compact(body.customer?.name, "Customer"),
      compact(device.device_name, "Site"),
      compact(device.device_ident, "Unknown"),
      compact(device.last_heartbeat, "No heartbeat recorded"),
      compact(device.offline_for, "10 minutes"),
    ],
  };
}

const prepared = body.event === "fmc_offline" ? fmcOfflineTemplateParameters() : auditTemplateParameters();
const common = {
  WA_PHONE_NUMBER_ID: input.WA_PHONE_NUMBER_ID,
  WA_ACCESS_TOKEN: input.WA_ACCESS_TOKEN,
  template_name: prepared.templateName,
  language_code: prepared.languageCode,
  template_parameters: prepared.parameters,
  event: body.event,
  customer_name: compact(body.customer?.name, "Customer"),
  audit_id: body.audit?.id ?? null,
  device_ident: body.device?.device_ident ?? null,
};

return input.recipients.map((recipient) => ({
  json: {
    ...common,
    phone_number: String(recipient).replace(/\D/g, ""),
  },
})).filter((item) => item.json.phone_number);

const deliveries = $input.all().map((item) => item.json);
const sent = deliveries.filter((item) => item.success).length;
const failed = deliveries.length - sent;
return [{ json: { success: failed === 0, provider: "whatsapp", sent, failed, deliveries, timestamp: new Date().toISOString() } }];
